      mps::MpsGraphKey("sum.dim_IntList", axes),
      {self_c},
      out,
      ^MPSGraphTensor*(MPSGraph* graph, NSArray<MPSGraphTensor*>* args) {
        MPSGraphTensor* y =
            [graph reductionSumWithTensor:args[0] axes:mps::MpsAxesArray(axes) name:nil];
        return y;
      });
  if (!ran) {
    return at::sum(self.cpu(), dim, keepdim, dtype).to(self.device());
  }
